import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register } from 'claude-code'

import type { LocalhostServer } from '../types'
import { parseCwds, parseListeners, shortPath, toServers } from './servers'

const PANE = 'localhost'
const servers = atom({ plugin: 'localhost', key: 'servers' } as const, [])

async function scan($: EngineInterface): Promise<LocalhostServer[]> {
  const listening = await $.process.run(['lsof', '-nP', '-iTCP', '-sTCP:LISTEN', '-F', 'pcn'])
  const listeners = parseListeners(listening.stdout)
  if (listeners.length === 0) {
    return []
  }

  const pids = [...new Set(listeners.map(listener => listener.pid))].join(',')
  const where = await $.process.run(['lsof', '-a', '-d', 'cwd', '-F', 'pn', '-p', pids])

  return toServers(listeners, parseCwds(where.stdout), await $.session.cwd())
}

async function refresh($: EngineInterface): Promise<LocalhostServer[]> {
  const found = await scan($).catch(() => [] as LocalhostServer[])
  await update($, servers, () => found)

  return found
}

async function stop($: EngineInterface, pids: number[]): Promise<void> {
  if (pids.length > 0) {
    await $.process.run(['kill', ...pids.map(String)]).catch(() => undefined)
    await $.clock.sleep(600)
  }
  await refresh($)
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    await $.command.register({
      name: 'localhost',
      description: 'Mostra i server localhost accesi, con i pulsanti per aprirli o fermarli',
    })

    return next(e)
  })

  on('command.run', { command: 'localhost' }, async $ => {
    const found = await refresh($)
    await $.ui.open({ id: PANE, title: 'localhost', focus: true, closeOnEscape: true })

    return { text: `${found.length} server localhost in ascolto.` }
  })

  // A dev server is usually started or stopped by a Bash call, so look again right after one.
  on('tool.call', { tool: 'Bash' }, async ($, e, next) => {
    const ran = await next(e)
    void refresh($)

    return ran
  })

  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const { Box, Button, Link, Text } = $.ui.resolve(e)
    const list = await read($, servers)
    const home = await $.env.get('HOME')
    const here = list.filter(server => server.isHere)

    return (
      <Box flexDirection="column">
        {list.length === 0 && <Text dimColor>Nessun server localhost acceso.</Text>}
        {list.map(server => (
          <Box key={`row-${server.pid}-${server.port}`} flexDirection="row" columnGap={1}>
            <Text bold color={server.isHere ? 'success' : undefined}>
              :{server.port}
            </Text>
            <Text dimColor>{server.command}</Text>
            <Box flexGrow={1}>
              <Text wrap="truncate-start" dimColor={!server.isHere}>
                {shortPath(server.cwd, home)}
              </Text>
            </Box>
            <Link href={`http://localhost:${server.port}`} label="apri" />
            <Button
              key={`stop-${server.pid}-${server.port}`}
              label="ferma"
              onPress={() => stop($, [server.pid])}
            />
          </Box>
        ))}
        <Box flexDirection="row" columnGap={1} marginTop={1}>
          {here.length > 0 && (
            <Button
              key="stop-here"
              label={`Ferma quelli di questo progetto (${here.length})`}
              variant="primary"
              onPress={() => stop($, here.map(server => server.pid))}
            />
          )}
          {list.length > 0 && (
            <Button
              key="stop-all"
              label="Ferma tutti"
              onPress={() => stop($, list.map(server => server.pid))}
            />
          )}
          <Button key="refresh" label="Aggiorna" onPress={() => void refresh($)} />
        </Box>
      </Box>
    )
  })
}

