import type { LocalhostServer } from '../types'

export type Listener = { pid: number; command: string; port: number }

// Reads `lsof -F pcn` output: a `p<pid>` line opens a process, `c<cmd>` names it,
// each `n<addr>:<port>` is one listening socket of it.
export function parseListeners(stdout: string): Listener[] {
  const found = new Map<string, Listener>()
  let pid = 0
  let command = ''

  for (const line of stdout.split('\n')) {
    const field = line[0]
    const value = line.slice(1)

    if (field === 'p') {
      pid = Number(value)
    } else if (field === 'c') {
      command = value
    } else if (field === 'n') {
      const port = Number(value.slice(value.lastIndexOf(':') + 1))
      if (pid > 0 && Number.isInteger(port) && port > 0) {
        found.set(`${pid}:${port}`, { pid, command, port })
      }
    }
  }

  return [...found.values()].sort((a, b) => a.port - b.port)
}

// Reads `lsof -a -d cwd -F pn` output into pid -> working directory.
export function parseCwds(stdout: string): Map<number, string> {
  const cwds = new Map<number, string>()
  let pid = 0

  for (const line of stdout.split('\n')) {
    if (line[0] === 'p') {
      pid = Number(line.slice(1))
    } else if (line[0] === 'n' && pid > 0) {
      cwds.set(pid, line.slice(1))
    }
  }

  return cwds
}

// Desktop apps and system daemons run from `/`; a dev server runs from a project folder.
export function toServers(
  listeners: Listener[],
  cwds: Map<number, string>,
  projectDir: string,
): LocalhostServer[] {
  return listeners
    .map(listener => ({ ...listener, cwd: cwds.get(listener.pid) ?? '/' }))
    .filter(server => server.cwd !== '/')
    .map(server => ({
      ...server,
      isHere: server.cwd === projectDir || server.cwd.startsWith(`${projectDir}/`),
    }))
}

export function shortPath(path: string, home: string | undefined): string {
  return home && path.startsWith(home) ? `~${path.slice(home.length)}` : path
}

